// ============================================================
// Extract Domains — parses Gappie's Postmaster Notification
// ============================================================
// Expected message format (multi-line, with emoji):
//
//   🔔 Postmaster Notification:
//   🕐 Date and Time: Feb 17nd, 2026, 8:38 am
//   🔍 Changes detected in your monitored domains:
//
//   🔹 withpersonaspace.com
//   – 🟢 Spam Rate decreased to 0.0%
//
//   🔹 personaforcreators.com
//   – 🔴 Spam Rate increased to 21.4%
//
// ============================================================

const text = items[0].json.text || items[0].json.message?.text || "";

// Only process Postmaster Notification messages (prevents bot reply loop)
if (!text.includes("Postmaster Notification")) {
  return [{ json: { flaggedDomains: [], skipped: true, reason: "Not a Postmaster Notification" } }];
}

const lines = text.split("\n").map(l => l.trim()).filter(l => l.length > 0);
const domains = [];

for (let i = 0; i < lines.length; i++) {
  // Match lines ending with a domain (strips leading emoji/whitespace/punctuation)
  const domainMatch = lines[i].match(/([a-zA-Z0-9][a-zA-Z0-9\-]*\.)+[a-zA-Z]{2,}$/);
  if (domainMatch && i + 1 < lines.length) {
    const domain = domainMatch[0].toLowerCase();
    // Next non-empty line should contain "Spam Rate increased/decreased to X.X%"
    const spamMatch = lines[i + 1].match(/Spam\s+Rate\s+(?:decreased|increased)\s+to\s+([\d.]+)%/i);
    if (spamMatch) {
      domains.push({
        domain: domain,
        spamRate: parseFloat(spamMatch[1]),
        direction: lines[i + 1].toLowerCase().includes("increased") ? "increased" : "decreased"
      });
      i++; // skip the spam rate line since we already consumed it
    }
  }
}

return [{ json: { flaggedDomains: domains } }];

// Build a formatted Slack reply summarizing domain health
const domains = items[0].json.flaggedDomains;

if (!domains || domains.length === 0) {
  return [{ json: { message: "No domain data found in this notification." } }];
}

const SPAM_THRESHOLD = 5; // percent — domains above this are flagged as critical

let message = "*Domain Health Summary*\n\n";
let criticalCount = 0;

for (const d of domains) {
  const emoji = d.spamRate > SPAM_THRESHOLD ? "🔴" : d.spamRate > 1 ? "🟡" : "🟢";
  const status = d.spamRate > SPAM_THRESHOLD ? "CRITICAL" : d.spamRate > 1 ? "WARNING" : "OK";

  if (d.spamRate > SPAM_THRESHOLD) criticalCount++;

  message += `${emoji} *${d.domain}* — Spam Rate: *${d.spamRate}%* (${d.direction}) [${status}]\n`;
}

if (criticalCount > 0) {
  message += `\n⚠️ *${criticalCount} domain(s) above ${SPAM_THRESHOLD}% spam threshold — action required!*`;
} else {
  message += `\n✅ All domains within acceptable spam rate thresholds.`;
}

return [{ json: { message: message } }];
